import xml.etree.ElementTree as ET,urllib.request,json,concurrent.futures
r=ET.parse('references/Hexalith.Builds/Props/Directory.Packages.props').getroot()
props={e.tag:e.text for e in r.iter() if len(e)==0 and e.text}
refs=[]
for n in r.iter('PackageVersion'):
 v=n.get('Version','')
 for k,x in props.items():v=v.replace('$('+k+')',x)
 refs.append((n.get('Include'),v))
def check(nv):
 n,v=nv
 try:
  with urllib.request.urlopen('https://api.nuget.org/v3-flatcontainer/'+n.lower()+'/index.json',timeout=30) as r:vs=json.load(r)['versions']
  stable=[x for x in vs if '-' not in x]
  latest=stable[-1] if stable else vs[-1]
  if v != latest:return (n,v,latest,'preview pin' if '-' in v else '')
 except Exception as e:return (n,v,'ERROR',str(e))
with concurrent.futures.ThreadPoolExecutor(max_workers=16) as ex:
 for out in ex.map(check,refs):
  if out:print(*out,flush=True)
print('Checked',len(refs),'central package declarations')
